    /** @param array<string,mixed> $payload @return array<string,mixed> */
    public function createTicket(string$organisationId,string$userId,string$role,?string$projectId,array$payload):array
    {
        $this->assertMember($organisationId,$userId,$role,['owner','admin','member']);
        if($projectId!==null)$this->assertProject($organisationId,$projectId);
        $normal=$this->policy->normaliseTicket($payload);$classification=$this->policy->classify(['title'=>$normal['title'],'description'=>$normal['description'],'deliverables'=>$normal['deliverables'],'requiredRegistrations'=>$normal['requiredRegistrations']]);
        return$this->transaction(function()use($organisationId,$userId,$projectId,$normal,$classification):array{
            $ticketId=Identifier::generate();
            $this->pdo->prepare('INSERT INTO job_tickets(id,organisation_id,project_id,poster_user_id,poster_type,title,description,deliverables,budget_min,budget_max,currency,deadline,location,phase,required_registrations,invitation_type,platform_fee_percent,platform_fee_disclosure,classification_snapshot,classification_sha256,automatic_award) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:project),UNHEX(:user),:poster,:title,:description,:deliverables,:minimum,:maximum,:currency,:deadline,:location,:phase,:registrations,:invitation,:fee,:disclosure,:classification,:sha,0)')->execute(['id'=>$ticketId,'o'=>$organisationId,'project'=>$projectId,'user'=>$userId,'poster'=>$normal['posterType'],'title'=>$normal['title'],'description'=>$normal['description'],'deliverables'=>$this->json($normal['deliverables']),'minimum'=>$normal['budget']['min'],'maximum'=>$normal['budget']['max'],'currency'=>$normal['budget']['currency'],'deadline'=>$normal['deadline'],'location'=>$normal['location'],'phase'=>$normal['phase'],'registrations'=>$this->json($normal['requiredRegistrations']),'invitation'=>$normal['invitationType'],'fee'=>$normal['platformFee']['percent'],'disclosure'=>$normal['platformFee']['disclosure'],'classification'=>$this->json($classification),'sha'=>$classification['sha256']]);
            $this->classificationRevision($organisationId,$ticketId,1,$classification,'Automatic deterministic advisory classification.',$userId,null);
            foreach($normal['invitedUserIds']as$recipient)$this->directInvite($organisationId,$projectId,$ticketId,$userId,$recipient,(string)$normal['title']);
            (new AuditService($this->pdo))->append($organisationId,$userId,'job_ticket.created','job_ticket',$ticketId,['projectId'=>$projectId,'invitationType'=>$normal['invitationType'],'classification'=>$classification['primaryCategory'],'automaticAward'=>false]);
            return$this->ticket($ticketId);
        });
    }

    /** @param array<string,mixed> $filters @return array{public:list<array<string,mixed>>,direct:list<array<string,mixed>>,recommended:list<array<string,mixed>>,active:list<array<string,mixed>>} */
    public function discover(string$organisationId,string$userId,string$role,array$filters):array
    {
        $this->assertMember($organisationId,$userId,$role,['owner','admin','member','viewer']);
        $conditions=["t.invitation_type='public'","t.status IN ('open','quoting')"];$parameters=[];
        if(is_string($filters['location']??null)&&trim($filters['location'])!==''){$conditions[]='t.location LIKE :location';$parameters['location']='%'.trim($filters['location']).'%';}
        if(is_string($filters['category']??null)&&trim($filters['category'])!==''){$conditions[]="JSON_UNQUOTE(JSON_EXTRACT(t.classification_snapshot,'$.primaryCategory'))=:category";$parameters['category']=trim($filters['category']);}
        $statement=$this->pdo->prepare('SELECT LOWER(HEX(t.id)) id FROM job_tickets t WHERE '.implode(' AND ',$conditions).' ORDER BY t.created_at DESC,t.id DESC LIMIT 200');$statement->execute($parameters);$public=array_map(fn(string$id):array=>$this->ticket($id),$statement->fetchAll(PDO::FETCH_COLUMN));
        $directStatement=$this->pdo->prepare("SELECT LOWER(HEX(t.id)) id FROM job_tickets t JOIN job_ticket_direct_invites i ON i.ticket_id=t.id WHERE i.recipient_user_id=UNHEX(:u) AND i.status NOT IN ('withdrawn','declined') AND t.status IN ('open','quoting') ORDER BY t.created_at DESC,t.id DESC LIMIT 200");$directStatement->execute(['u'=>$userId]);$direct=array_map(fn(string$id):array=>$this->ticket($id),$directStatement->fetchAll(PDO::FETCH_COLUMN));
        $activeStatement=$this->pdo->prepare("SELECT LOWER(HEX(id)) id FROM job_tickets WHERE (poster_user_id=UNHEX(:poster_user) OR holder_user_id=UNHEX(:holder_user)) AND status NOT IN ('completed','cancelled') ORDER BY updated_at DESC,id DESC LIMIT 200");$activeStatement->execute(['poster_user'=>$userId,'holder_user'=>$userId]);$active=array_map(fn(string$id):array=>$this->ticket($id),$activeStatement->fetchAll(PDO::FETCH_COLUMN));
        $profiles=$this->matchProfiles($organisationId,$userId);$recommended=[];foreach($public as$ticket){$matches=$this->policy->matchRecipients($ticket['classification'],$ticket['location'],$profiles);if($matches!==[]&&$matches[0]['userId']===$userId)$recommended[]=[...$ticket,'matchScore'=>$matches[0]['score'],'matchReasons'=>$matches[0]['reasons'],'advisoryOnly'=>true];}
        usort($recommended,static fn(array$a,array$b):int=>$b['matchScore']<=>$a['matchScore']?:strcmp($a['id'],$b['id']));
        return['public'=>$public,'direct'=>$direct,'recommended'=>$recommended,'active'=>$active];
    }

    /** @param array<string,mixed> $payload @return array<string,mixed> */
