            return['id'=>$id,'ticketId'=>$ticketId,'status'=>'submitted','amount'=>$quote['amount'],'currency'=>$quote['currency'],'snapshotSha256'=>$evidence['sha256'],'ticketVersion'=>$version];
        });
    }

