    /** @return array<string,mixed> */private function freelancerProfileRow(string$id,bool$lock):array{$s=$this->pdo->prepare('SELECT LOWER(HEX(id)) id,LOWER(HEX(organisation_id)) organisation_id,LOWER(HEX(user_id)) user_id,display_name,discipline,registration_status,council,council_registration_number,DATE_FORMAT(council_expiry_date,\'%Y-%m-%d\') council_expiry_date,public_summary,portfolio_refs,service_areas,capacity_status,identity_verified,supervisor_required,independent_appointment_permitted,status,version FROM freelancer_profiles WHERE id=UNHEX(:id)'.($lock?' FOR UPDATE':''));$s->execute(['id'=>$this->id($id,'freelancer_profile_not_found')]);$r=$s->fetch();if(!is_array($r))throw new JobTicketMarketplaceException('freelancer_profile_not_found');return$r;}
