    /** @return array<string,mixed> */private function engagementRow(string$id,bool$lock):array{$s=$this->pdo->prepare('SELECT LOWER(HEX(id)) id,LOWER(HEX(organisation_id)) organisation_id,LOWER(HEX(project_id)) project_id,LOWER(HEX(ticket_id)) ticket_id,LOWER(HEX(quotation_id)) quotation_id,LOWER(HEX(freelancer_profile_id)) freelancer_profile_id,LOWER(HEX(supervision_route_id)) supervision_route_id,LOWER(HEX(holder_organisation_id)) holder_organisation_id,LOWER(HEX(holder_user_id)) holder_user_id,scope_snapshot,agreed_amount,currency,status,human_accepted,version FROM freelancer_engagements WHERE id=UNHEX(:id)'.($lock?' FOR UPDATE':''));$s->execute(['id'=>$this->id($id,'freelancer_engagement_not_found')]);$r=$s->fetch();if(!is_array($r))throw new JobTicketMarketplaceException('freelancer_engagement_not_found');return$r;}
