    /** @return array<string,mixed> */private function deliverable(string$id):array{$s=$this->pdo->prepare('SELECT LOWER(HEX(id)) id,LOWER(HEX(engagement_id)) engagement_id,name,description,LOWER(HEX(current_revision_id)) current_revision_id,status,external_issue_ready,version FROM freelancer_deliverables WHERE id=UNHEX(:id)');$s->execute(['id'=>$this->id($id,'freelancer_deliverable_not_found')]);$r=$s->fetch();if(!is_array($r))throw new JobTicketMarketplaceException('freelancer_deliverable_not_found');$rev=$this->pdo->prepare('SELECT LOWER(HEX(id)) id,revision,file_manifest,file_manifest_sha256,submission_note FROM freelancer_deliverable_revisions WHERE id=UNHEX(:id) AND deliverable_id=UNHEX(:deliverable)');$rev->execute(['id'=>$r['current_revision_id'],'deliverable'=>$id]);$revision=$rev->fetch();if(!is_array($revision))throw new JobTicketMarketplaceException('freelancer_deliverable_integrity_failed');return['id'=>$r['id'],'engagementId'=>$r['engagement_id'],'name'=>$r['name'],'description'=>$r['description'],'status'=>$r['status'],'externalIssueReady'=>(bool)$r['external_issue_ready'],'version'=>(int)$r['version'],'currentRevision'=>['id'=>$revision['id'],'revision'=>(int)$revision['revision'],'files'=>$this->decode($revision['file_manifest']),'fileManifestSha256'=>$revision['file_manifest_sha256'],'submissionNote'=>$revision['submission_note']]];}
    /** @return list<array{storedFileId:?string,name:string,sha256:string}> */private function normaliseFiles(mixed$value):array{if(!is_array($value)||$value===[]||count($value)>100)throw new JobTicketMarketplaceException('freelancer_deliverable_files_invalid');$files=[];foreach($value as$file){if(!is_array($file))throw new JobTicketMarketplaceException('freelancer_deliverable_files_invalid');$stored=$file['storedFileId']??null;if($stored!==null)$stored=$this->id(is_string($stored)?$stored:'','freelancer_deliverable_file_id_invalid');$name=$this->text($file['name']??null,255,'freelancer_deliverable_file_name_required');$sha=$file['sha256']??null;if(!is_string($sha)||preg_match('/\A[a-f0-9]{64}\z/',$sha)!==1)throw new JobTicketMarketplaceException('freelancer_deliverable_file_hash_invalid');$files[]=['storedFileId'=>$stored,'name'=>$name,'sha256'=>$sha];}usort($files,static fn(array$a,array$b):int=>strcmp($a['name'],$b['name'])?:strcmp($a['sha256'],$b['sha256']));return$files;}
    /** @return array<string,mixed>|null */private function verifiedRecord(string$o,string$u,?string$kind):?array{$sql="SELECT LOWER(HEX(id)) id,kind,grade FROM verification_records WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u) AND grade IN ('manually_reviewed','externally_verified') AND reviewed_by IS NOT NULL AND reviewed_by<>user_id AND (expires_on IS NULL OR expires_on>=UTC_DATE())".($kind===null?'':' AND kind=:kind')." ORDER BY FIELD(grade,'externally_verified','manually_reviewed'),reviewed_at DESC,id DESC LIMIT 1";$s=$this->pdo->prepare($sql);$parameters=['o'=>$o,'u'=>$u];if($kind!==null)$parameters['kind']=$kind;$s->execute($parameters);$r=$s->fetch();return is_array($r)?$r:null;}
    private function assertVerifiedSupervisor(string$o,string$u,string$discipline):void{if($this->verifiedRecord($o,$u,'professional_registration')===null)throw new JobTicketMarketplaceException('freelancer_supervisor_verification_required');$s=$this->pdo->prepare('SELECT profession FROM professional_profiles WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u) AND directory_visible=1');$s->execute(['o'=>$o,'u'=>$u]);if($s->fetchColumn()!==$discipline)throw new JobTicketMarketplaceException('freelancer_supervisor_discipline_unverified');}
