    private function executionRecord(array$ticket,string$actor,string$type,string$title,string$status,array$payload):void{if($ticket['project_id']===null)return;$this->pdo->prepare('INSERT INTO project_records(id,organisation_id,project_id,phase,module_key,record_type,title,status,payload,approvals,linked_record_ids,created_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:project),:phase,\'job_ticket_marketplace\',:type,:title,:status,:payload,:approvals,\'[]\',UNHEX(:actor))')->execute(['id'=>Identifier::generate(),'o'=>$ticket['organisation_id'],'project'=>$ticket['project_id'],'phase'=>ProjectPhase::TenderProcurement->value,'type'=>$type,'title'=>$title,'status'=>$status,'payload'=>$this->json($payload),'approvals'=>$this->json(['required'=>true,'humanApprovalConfirmed'=>true,'approvedBy'=>$actor]),'actor'=>$actor]);}

